const app = document.querySelector('#app');

function element(tag, text) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  return node;
}

function validDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split('-').map(Number);
  if (year < 1 || month < 1 || month > 12) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= days[month - 1];
}

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to load projects');
  return data;
}

function alertBox() {
  const alert = element('p');
  alert.setAttribute('role', 'alert');
  alert.hidden = true;
  app.append(alert);
  return alert;
}

async function showProjects() {
  app.replaceChildren(element('h1', 'Workboard'));
  const form = element('form');
  const label = element('label', 'Project name');
  label.htmlFor = 'project-name';
  const input = element('input');
  input.id = 'project-name';
  input.name = 'name';
  input.type = 'text';
  const create = element('button', 'Create project');
  create.type = 'submit';
  form.append(label, input, create);
  app.append(form);
  const alert = alertBox();
  const filterLabel = element('label', 'Project filter');
  filterLabel.htmlFor = 'project-filter';
  const filter = element('select');
  filter.id = 'project-filter';
  for (const name of ['Active', 'Archived']) {
    const option = element('option', name);
    option.value = name;
    filter.append(option);
  }
  app.append(filterLabel, filter);
  let projects = [];
  const list = element('section');
  list.setAttribute('aria-label', 'Projects');
  app.append(list);

  function render() {
    list.replaceChildren();
    for (const project of projects) {
      if (Boolean(project.archived) !== (filter.value === 'Archived')) continue;
      const row = element('div');
      row.className = 'project-row';
      row.dataset.testid = 'project-row';
      const open = element('button', 'Open project');
      open.type = 'button';
      open.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
      const summary = element('span', `${project.completed}/${project.total} completed`);
      summary.dataset.testid = 'project-summary';
      const archive = element('button', project.archived ? 'Restore project' : 'Archive project');
      archive.type = 'button';
      archive.addEventListener('click', async () => {
        archive.disabled = true;
        alert.hidden = true;
        try {
          await request(`/api/projects/${project.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ archived: !project.archived }),
          });
          await refresh();
        } catch (error) { showError(error); }
        finally { archive.disabled = false; }
      });
      row.append(element('span', project.name), summary, open, archive);
      list.append(row);
    }
  }
  function showError(error) {
    alert.textContent = error.message;
    alert.hidden = false;
  }
  async function refresh() {
    projects = await request('/api/projects');
    render();
  }
  filter.addEventListener('change', render);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) return showError(new Error('Project name is required'));
    create.disabled = true;
    alert.hidden = true;
    try {
      await request('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      input.value = '';
      await refresh();
      input.focus();
    } catch (error) { showError(error); }
    finally { create.disabled = false; }
  });
  try { await refresh(); }
  catch (error) { showError(error); }
}

async function showProject(id) {
  app.replaceChildren();
  const back = element('button', 'Projects');
  back.type = 'button';
  back.addEventListener('click', () => { location.href = '/'; });
  app.append(back);
  const alert = alertBox();
  try {
    const project = await request(`/api/projects/${id}`);
    const destinations = (await request('/api/projects')).filter(other => !other.archived && other.id !== project.id);
    const heading = element('h1', project.name);
    app.prepend(heading);
    document.title = `${project.name} — Workboard`;
    if (project.archived) app.append(element('p', 'Archived project'));
    const renameForm = element('form');
    const renameLabel = element('label', 'New project name');
    renameLabel.htmlFor = 'new-project-name';
    const renameInput = element('input');
    renameInput.id = 'new-project-name';
    renameInput.type = 'text';
    renameInput.disabled = Boolean(project.archived);
    const rename = element('button', 'Rename project');
    rename.type = 'submit';
    rename.disabled = Boolean(project.archived);
    renameForm.append(renameLabel, renameInput, rename);
    app.append(renameForm);
    renameForm.addEventListener('submit', async (event) => {
      event.preventDefault();
      if (project.archived) return;
      const name = renameInput.value.trim();
      if (!name) return showError(new Error('Project name is required'));
      rename.disabled = true;
      alert.hidden = true;
      try {
        const saved = await request(`/api/projects/${id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name }),
        });
        project.name = saved.name;
        heading.textContent = saved.name;
        document.title = `${saved.name} — Workboard`;
        renameInput.value = '';
        renameInput.focus();
      } catch (error) { showError(error); }
      finally { rename.disabled = Boolean(project.archived); }
    });
    const defaultLabel = element('label', 'Default task priority');
    defaultLabel.htmlFor = 'default-task-priority';
    const defaultPriority = element('select');
    defaultPriority.id = defaultLabel.htmlFor;
    for (const name of ['Low', 'Normal', 'High']) {
      const option = element('option', name);
      option.value = name;
      defaultPriority.append(option);
    }
    defaultPriority.value = project.default_priority;
    defaultPriority.disabled = Boolean(project.archived);
    app.append(defaultLabel, defaultPriority);
    defaultPriority.addEventListener('change', async () => {
      if (project.archived) return;
      defaultPriority.disabled = true;
      alert.hidden = true;
      try {
        const saved = await request(`/api/projects/${id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ default_priority: defaultPriority.value }),
        });
        project.default_priority = saved.default_priority;
      } catch (error) { showError(error); }
      finally {
        defaultPriority.value = project.default_priority;
        defaultPriority.disabled = Boolean(project.archived);
      }
    });
    const form = element('form');
    const label = element('label', 'Task title');
    label.htmlFor = 'task-title';
    const input = element('input');
    input.id = 'task-title';
    input.type = 'text';
    const create = element('button', 'Create task');
    create.type = 'submit';
    create.disabled = Boolean(project.archived);
    form.append(label, input, create);
    const filterLabel = element('label', 'Task filter');
    filterLabel.htmlFor = 'task-filter';
    const filter = element('select');
    filter.id = 'task-filter';
    for (const name of ['All', 'Open', 'Completed']) {
      const option = element('option', name);
      option.value = name;
      filter.append(option);
    }
    const priorityFilterLabel = element('label', 'Priority filter');
    priorityFilterLabel.htmlFor = 'priority-filter';
    const priorityFilter = element('select');
    priorityFilter.id = 'priority-filter';
    for (const name of ['All', 'Low', 'Normal', 'High']) {
      const option = element('option', name);
      option.value = name;
      priorityFilter.append(option);
    }
    const rangeForm = element('form');
    const fromLabel = element('label', 'Due from');
    fromLabel.htmlFor = 'due-from';
    const fromInput = element('input');
    fromInput.id = fromLabel.htmlFor;
    fromInput.type = 'text';
    const throughLabel = element('label', 'Due through');
    throughLabel.htmlFor = 'due-through';
    const throughInput = element('input');
    throughInput.id = throughLabel.htmlFor;
    throughInput.type = 'text';
    const applyRange = element('button', 'Apply due range');
    applyRange.type = 'submit';
    rangeForm.append(fromLabel, fromInput, throughLabel, throughInput, applyRange);
    let dueFrom = '';
    let dueThrough = '';
    rangeForm.addEventListener('submit', (event) => {
      event.preventDefault();
      const from = fromInput.value.trim();
      const through = throughInput.value.trim();
      if ((from && !validDate(from)) || (through && !validDate(through))) {
        return showError(new Error('Due range must use valid YYYY-MM-DD dates'));
      }
      if (from && through && from > through) {
        return showError(new Error('Due from must not be after Due through'));
      }
      dueFrom = from;
      dueThrough = through;
      fromInput.value = from;
      throughInput.value = through;
      alert.hidden = true;
      render();
    });
    const list = element('section');
    list.setAttribute('aria-label', 'Tasks');
    app.append(form, filterLabel, filter, priorityFilterLabel, priorityFilter, rangeForm, list);
    let tasks = [];
    function showError(error) {
      alert.textContent = error.message;
      alert.hidden = false;
    }
    function render() {
      list.replaceChildren();
      for (const task of tasks) {
        if (filter.value === 'Open' && task.completed) continue;
        if (filter.value === 'Completed' && !task.completed) continue;
        if (priorityFilter.value !== 'All' && task.priority !== priorityFilter.value) continue;
        if ((dueFrom || dueThrough) && (!task.due_date ||
            (dueFrom && task.due_date < dueFrom) ||
            (dueThrough && task.due_date > dueThrough))) continue;
        const row = element('div');
        row.className = 'task-row';
        row.dataset.testid = 'task-row';
        const checkbox = element('input');
        checkbox.type = 'checkbox';
        checkbox.checked = task.completed;
        checkbox.disabled = Boolean(project.archived);
        checkbox.setAttribute('aria-label', `Complete ${task.title}`);
        checkbox.addEventListener('change', async () => {
          checkbox.disabled = true;
          alert.hidden = true;
          try {
            const saved = await request(`/api/projects/${id}/tasks/${task.id}`, {
              method: 'PATCH',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ completed: checkbox.checked }),
            });
            task.completed = saved.completed;
            render();
          } catch (error) {
            checkbox.checked = task.completed;
            showError(error);
          } finally { checkbox.disabled = false; }
        });
        const titleText = element('span', task.title);
        const taskRenameForm = element('form');
        const taskRenameLabel = element('label', 'New task title');
        taskRenameLabel.htmlFor = `new-task-title-${task.id}`;
        const taskRenameInput = element('input');
        taskRenameInput.id = taskRenameLabel.htmlFor;
        taskRenameInput.type = 'text';
        taskRenameInput.disabled = Boolean(project.archived);
        const taskRename = element('button', 'Rename task');
        taskRename.type = 'submit';
        taskRename.disabled = Boolean(project.archived);
        taskRenameForm.append(taskRenameLabel, taskRenameInput, taskRename);
        taskRenameForm.addEventListener('submit', async (event) => {
          event.preventDefault();
          if (project.archived) return;
          const title = taskRenameInput.value.trim();
          if (!title) return showError(new Error('Task title is required'));
          taskRename.disabled = true;
          alert.hidden = true;
          try {
            const saved = await request(`/api/projects/${id}/tasks/${task.id}`, {
              method: 'PATCH',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ title }),
            });
            task.title = saved.title;
            titleText.textContent = saved.title;
            checkbox.setAttribute('aria-label', `Complete ${saved.title}`);
            taskRenameInput.value = '';
            taskRenameInput.focus();
          } catch (error) { showError(error); }
          finally { taskRename.disabled = Boolean(project.archived); }
        });
        const priorityLabel = element('label', 'Task priority');
        priorityLabel.htmlFor = `task-priority-${task.id}`;
        const priority = element('select');
        priority.id = priorityLabel.htmlFor;
        for (const name of ['Low', 'Normal', 'High']) {
          const option = element('option', name);
          option.value = name;
          priority.append(option);
        }
        priority.value = task.priority;
        priority.disabled = Boolean(project.archived);
        priority.addEventListener('change', async () => {
          priority.disabled = true;
          alert.hidden = true;
          try {
            const saved = await request(`/api/projects/${id}/tasks/${task.id}`, {
              method: 'PATCH',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ priority: priority.value }),
            });
            task.priority = saved.priority;
            render();
          } catch (error) { showError(error); }
          finally {
            priority.value = task.priority;
            priority.disabled = Boolean(project.archived);
          }
        });
        const dueForm = element('form');
        const dueLabel = element('label', 'Task due date');
        dueLabel.htmlFor = `task-due-date-${task.id}`;
        const dueInput = element('input');
        dueInput.id = dueLabel.htmlFor;
        dueInput.type = 'text';
        dueInput.value = task.due_date;
        dueInput.disabled = Boolean(project.archived);
        const saveDue = element('button', 'Save due date');
        saveDue.type = 'submit';
        saveDue.disabled = Boolean(project.archived);
        dueForm.append(dueLabel, dueInput, saveDue);
        dueForm.addEventListener('submit', async (event) => {
          event.preventDefault();
          if (project.archived) return;
          saveDue.disabled = true;
          alert.hidden = true;
          try {
            const saved = await request(`/api/projects/${id}/tasks/${task.id}`, {
              method: 'PATCH',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ due_date: dueInput.value }),
            });
            task.due_date = saved.due_date;
            dueInput.value = saved.due_date;
            render();
          } catch (error) {
            dueInput.value = task.due_date;
            showError(error);
          } finally { saveDue.disabled = Boolean(project.archived); }
        });
        const moveForm = element('form');
        const destinationLabel = element('label', 'Destination project');
        destinationLabel.htmlFor = `destination-project-${task.id}`;
        const destination = element('select');
        destination.id = destinationLabel.htmlFor;
        for (const other of destinations) {
          const option = element('option', other.name);
          option.value = String(other.id);
          destination.append(option);
        }
        const move = element('button', 'Move task');
        move.type = 'submit';
        const cannotMove = Boolean(project.archived) || destinations.length === 0;
        destination.disabled = cannotMove;
        move.disabled = cannotMove;
        moveForm.append(destinationLabel, destination, move);
        moveForm.addEventListener('submit', async (event) => {
          event.preventDefault();
          if (cannotMove) return;
          move.disabled = true;
          alert.hidden = true;
          try {
            await request(`/api/projects/${id}/tasks/${task.id}`, {
              method: 'PATCH',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ destination_project_id: Number(destination.value) }),
            });
            tasks = tasks.filter(other => other.id !== task.id);
            render();
          } catch (error) { showError(error); }
          finally { move.disabled = cannotMove; }
        });
        row.append(titleText, checkbox, taskRenameForm, priorityLabel, priority, dueForm, moveForm);
        list.append(row);
      }
    }
    filter.addEventListener('change', render);
    priorityFilter.addEventListener('change', render);
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      if (project.archived) return;
      const title = input.value.trim();
      if (!title) return showError(new Error('Task title is required'));
      create.disabled = true;
      alert.hidden = true;
      try {
        const task = await request(`/api/projects/${id}/tasks`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ title }),
        });
        tasks.push(task);
        input.value = '';
        render();
        input.focus();
      } catch (error) { showError(error); }
      finally { create.disabled = false; }
    });
    tasks = await request(`/api/projects/${id}/tasks`);
    render();
  } catch (error) {
    alert.textContent = error.message;
    alert.hidden = false;
  }
}

const match = location.pathname.match(/^\/projects\/(\d+)$/);
if (match) showProject(match[1]);
else showProjects();

import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const dbPath = process.env.DB_PATH || './data/workboard.sqlite';
if (dbPath !== ':memory:') mkdirSync(dirname(resolve(dbPath)), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
db.exec(`PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
)`);
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'priority')) {
  db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'default_priority')) {
  db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'due_date')) {
  db.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'position')) {
  db.exec('ALTER TABLE tasks ADD COLUMN position INTEGER NOT NULL DEFAULT 0; UPDATE tasks SET position = id');
}
// Keep a stable ordering slot for every project a task has visited. Seed
// existing tasks from their current positions without overwriting remembered slots.
db.exec(`CREATE TABLE IF NOT EXISTS task_positions (
  task_id INTEGER NOT NULL REFERENCES tasks(id),
  project_id INTEGER NOT NULL REFERENCES projects(id),
  position INTEGER NOT NULL,
  PRIMARY KEY (task_id, project_id),
  UNIQUE (project_id, position)
);
INSERT OR IGNORE INTO task_positions (task_id, project_id, position)
  SELECT id, project_id, position FROM tasks;`);
const nextPosition = db.prepare('SELECT COALESCE(MAX(position), 0) + 1 AS position FROM task_positions WHERE project_id = ?');
const rememberedPosition = db.prepare('SELECT position FROM task_positions WHERE task_id = ? AND project_id = ?');
const savePosition = db.prepare('INSERT INTO task_positions (task_id, project_id, position) VALUES (?, ?, ?)');
function transaction(action) {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = action();
    db.exec('COMMIT');
    return result;
  } catch (error) {
    db.exec('ROLLBACK');
    throw error;
  }
}
const listTasks = db.prepare('SELECT id, project_id, title, completed, priority, due_date FROM tasks WHERE project_id = ? ORDER BY position, id');
const findTask = db.prepare('SELECT id, project_id, title, completed, priority, due_date FROM tasks WHERE project_id = ? AND id = ?');
const insertTask = db.prepare('INSERT INTO tasks (project_id, title, priority, position) VALUES (?, ?, ?, ?)');
const moveTask = db.prepare('UPDATE tasks SET project_id = ?, position = ? WHERE project_id = ? AND id = ?');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = db.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const prioritizeTask = db.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
const setDueDate = db.prepare('UPDATE tasks SET due_date = ? WHERE project_id = ? AND id = ?');

function validDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split('-').map(Number);
  if (year < 1 || month < 1 || month > 12) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= days[month - 1];
}

const taskJson = task => ({ ...task, completed: Boolean(task.completed) });
const projectSelect = `SELECT p.id, p.name, p.archived, p.default_priority,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id) AS total,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id AND completed = 1) AS completed
  FROM projects p`;
const listProjects = db.prepare(`${projectSelect} ORDER BY p.id`);
const findProject = db.prepare(`${projectSelect} WHERE p.id = ?`);
const archiveProject = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
const setDefaultPriority = db.prepare('UPDATE projects SET default_priority = ? WHERE id = ?');
const insertProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const page = readFileSync(new URL('./public/index.html', import.meta.url));
const script = readFileSync(new URL('./public/app.js', import.meta.url));
const styles = readFileSync(new URL('./public/style.css', import.meta.url));

function send(res, status, body, type = 'application/json; charset=utf-8') {
  res.writeHead(status, { 'Content-Type': type, 'Cache-Control': 'no-store' });
  res.end(type.startsWith('application/json') ? JSON.stringify(body) : body);
}

const server = http.createServer(async (req, res) => {
  try {
    const path = new URL(req.url, 'http://localhost').pathname;
    if (req.method === 'GET' && path === '/health') return send(res, 200, { status: 'ok' });
    if (req.method === 'GET' && path === '/api/projects') return send(res, 200, listProjects.all());
    const match = path.match(/^\/api\/projects\/(\d+)$/);
    if (req.method === 'GET' && match) {
      const project = findProject.get(match[1]);
      return project ? send(res, 200, project) : send(res, 404, { error: 'Project not found' });
    }
    const tasksMatch = path.match(/^\/api\/projects\/(\d+)\/tasks$/);
    const taskMatch = path.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
    if (req.method === 'GET' && tasksMatch) {
      if (!findProject.get(tasksMatch[1])) return send(res, 404, { error: 'Project not found' });
      return send(res, 200, listTasks.all(tasksMatch[1]).map(taskJson));
    }
    if ((req.method === 'POST' && (path === '/api/projects' || tasksMatch)) ||
        (req.method === 'PATCH' && (taskMatch || match))) {
      let body = '';
      for await (const chunk of req) {
        body += chunk;
        if (Buffer.byteLength(body) > 65536) return send(res, 413, { error: 'Request too large' });
      }
      let input;
      try { input = JSON.parse(body); }
      catch { return send(res, 400, { error: 'Invalid JSON' }); }
      if (req.method === 'PATCH' && match) {
        const project = findProject.get(match[1]);
        if (!project) return send(res, 404, { error: 'Project not found' });
        if (input && Object.hasOwn(input, 'name')) {
          if (project.archived) return send(res, 409, { error: 'Archived project' });
          const name = typeof input.name === 'string' ? input.name.trim() : '';
          if (!name) return send(res, 400, { error: 'Project name is required' });
          renameProject.run(name, match[1]);
        } else if (input && Object.hasOwn(input, 'default_priority')) {
          if (project.archived) return send(res, 409, { error: 'Archived project' });
          if (!['Low', 'Normal', 'High'].includes(input.default_priority)) {
            return send(res, 400, { error: 'Priority must be Low, Normal, or High' });
          }
          setDefaultPriority.run(input.default_priority, match[1]);
        } else {
          if (typeof input?.archived !== 'boolean') return send(res, 400, { error: 'Archived must be a boolean' });
          archiveProject.run(Number(input.archived), match[1]);
        }
        return send(res, 200, findProject.get(match[1]));
      }
      if (tasksMatch) {
        const project = findProject.get(tasksMatch[1]);
        if (!project) return send(res, 404, { error: 'Project not found' });
        if (project.archived) return send(res, 409, { error: 'Archived project' });
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return send(res, 400, { error: 'Task title is required' });
        const result = transaction(() => {
          const position = nextPosition.get(project.id).position;
          const inserted = insertTask.run(project.id, title, project.default_priority, position);
          savePosition.run(inserted.lastInsertRowid, project.id, position);
          return inserted;
        });
        return send(res, 201, taskJson(findTask.get(tasksMatch[1], result.lastInsertRowid)));
      }
      if (taskMatch) {
        if (!findTask.get(taskMatch[1], taskMatch[2])) return send(res, 404, { error: 'Task not found' });
        if (findProject.get(taskMatch[1]).archived) return send(res, 409, { error: 'Archived project' });
        if (input && Object.hasOwn(input, 'destination_project_id')) {
          const destination = Number.isSafeInteger(input.destination_project_id)
            ? findProject.get(input.destination_project_id) : null;
          if (!destination || destination.id === Number(taskMatch[1])) {
            return send(res, 400, { error: 'Choose another active project' });
          }
          if (destination.archived) return send(res, 409, { error: 'Archived project' });
          transaction(() => {
            let slot = rememberedPosition.get(taskMatch[2], destination.id);
            if (!slot) {
              slot = nextPosition.get(destination.id);
              savePosition.run(taskMatch[2], destination.id, slot.position);
            }
            moveTask.run(destination.id, slot.position, taskMatch[1], taskMatch[2]);
          });
          return send(res, 200, taskJson(findTask.get(destination.id, taskMatch[2])));
        } else if (input && Object.hasOwn(input, 'title')) {
          const title = typeof input.title === 'string' ? input.title.trim() : '';
          if (!title) return send(res, 400, { error: 'Task title is required' });
          renameTask.run(title, taskMatch[1], taskMatch[2]);
        } else if (input && Object.hasOwn(input, 'priority')) {
          if (!['Low', 'Normal', 'High'].includes(input.priority)) {
            return send(res, 400, { error: 'Priority must be Low, Normal, or High' });
          }
          prioritizeTask.run(input.priority, taskMatch[1], taskMatch[2]);
        } else if (input && Object.hasOwn(input, 'due_date')) {
          const date = typeof input.due_date === 'string' ? input.due_date.trim() : null;
          if (date === null || (date !== '' && !validDate(date))) {
            return send(res, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
          }
          setDueDate.run(date, taskMatch[1], taskMatch[2]);
        } else {
          if (typeof input?.completed !== 'boolean') return send(res, 400, { error: 'Completion must be a boolean' });
          updateTask.run(Number(input.completed), taskMatch[1], taskMatch[2]);
        }
        return send(res, 200, taskJson(findTask.get(taskMatch[1], taskMatch[2])));
      }
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return send(res, 400, { error: 'Project name is required' });
      const result = insertProject.run(name);
      return send(res, 201, findProject.get(result.lastInsertRowid));
    }
    if (req.method === 'GET' && (path === '/' || /^\/projects\/\d+$/.test(path))) {
      return send(res, 200, page, 'text/html; charset=utf-8');
    }
    if (req.method === 'GET' && path === '/app.js') return send(res, 200, script, 'text/javascript; charset=utf-8');
    if (req.method === 'GET' && path === '/style.css') return send(res, 200, styles, 'text/css; charset=utf-8');
    send(res, 404, { error: 'Not found' });
  } catch (error) {
    console.error(error);
    if (!res.headersSent) send(res, 500, { error: 'Something went wrong' });
    else res.end();
  }
});
server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import vm from 'node:vm';

// Small DOM adapter executes the actual browser script without dependencies.
class Element {
  constructor(tag) {
    this.tag = tag;
    this.children = [];
    this.attributes = {};
    this.dataset = {};
    this.listeners = {};
    this.value = '';
  }
  append(...nodes) {
    this.children.push(...nodes);
    if (this.tag === 'select' && !this.value) this.value = this.children[0].value;
  }
  prepend(...nodes) { this.children.unshift(...nodes); }
  replaceChildren(...nodes) { this.children = nodes; }
  setAttribute(key, value) { this.attributes[key] = value; }
  addEventListener(name, handler) { this.listeners[name] = handler; }
  focus() {}
  async fire(name) { await this.listeners[name]({ preventDefault() {} }); }
}
const descendants = node => [node, ...node.children.flatMap(descendants)];

async function page(archived = false, dates = [], otherProjects = []) {
  const app = new Element('main');
  const tasks = [
    { id: 1, title: 'First', completed: false, priority: 'Low' },
    { id: 2, title: 'Second', completed: true, priority: 'High' },
    { id: 3, title: 'Third', completed: false, priority: 'High' },
    { id: 4, title: 'Fourth', completed: true, priority: 'Normal' },
  ];
  for (const task of tasks) task.due_date = dates[task.id - 1] || '';
  const project = { id: 1, name: 'Project', archived, default_priority: 'Normal' };
  const context = vm.createContext({
    document: { querySelector: () => app, createElement: tag => new Element(tag) },
    location: { pathname: '/projects/1' },
    fetch: async (path, options) => {
      let data;
      if (options) {
        const input = JSON.parse(options.body);
        if (path === '/api/projects/1') {
          Object.assign(project, input);
          data = project;
        } else if (path.endsWith('/tasks')) {
          data = { id: tasks.length + 1, ...input, completed: false, priority: project.default_priority, due_date: '' };
          tasks.push(data);
        } else {
          const task = tasks.find(task => task.id === Number(path.split('/').at(-1)));
          Object.assign(task, input);
          data = task;
        }
      } else data = path === '/api/projects' ? [project, ...otherProjects] : path.endsWith('/tasks') ? tasks : project;
      return { ok: true, json: async () => structuredClone(data) };
    },
  });
  vm.runInContext(await readFile(new URL('../public/app.js', import.meta.url), 'utf8'), context);
  await new Promise(resolve => setImmediate(resolve));
  const byId = id => descendants(app).find(node => node.id === id);
  const rows = () => descendants(app).filter(node => node.dataset.testid === 'task-row');
  const titles = () => rows().map(row => row.children[0].textContent);
  return { app, tasks, project, byId, rows, titles };
}

test('combined filters retain selections, creation order, and re-evaluate edits', async () => {
  const { app, tasks, byId, rows, titles } = await page();
  const completion = byId('task-filter');
  const priority = byId('priority-filter');
  assert.equal(completion.value, 'All');
  assert.equal(priority.value, 'All');
  assert.deepEqual(priority.children.map(option => option.textContent), ['All', 'Low', 'Normal', 'High']);
  for (const status of ['All', 'Open', 'Completed']) {
    completion.value = status;
    await completion.fire('change');
    for (const level of ['All', 'Low', 'Normal', 'High']) {
      priority.value = level;
      await priority.fire('change');
      assert.equal(completion.value, status);
      assert.deepEqual(titles(), tasks.filter(task =>
        (status === 'All' || task.completed === (status === 'Completed')) &&
        (level === 'All' || task.priority === level)).map(task => task.title));
    }
  }
  completion.value = 'Open';
  await completion.fire('change');
  assert.equal(priority.value, 'High');
  const renameForm = rows()[0].children.find(node => node.tag === 'form');
  renameForm.children[1].value = '  Renamed  ';
  await renameForm.fire('submit');
  assert.deepEqual(titles(), ['Renamed']);
  assert.equal(rows()[0].children[1].attributes['aria-label'], 'Complete Renamed');
  assert.equal(completion.value, 'Open');
  assert.equal(priority.value, 'High');
  const taskPriority = byId('task-priority-3');
  taskPriority.value = 'Low';
  await taskPriority.fire('change');
  assert.deepEqual(titles(), []);
  assert.equal(priority.value, 'High');
  priority.value = 'Low';
  await priority.fire('change');
  assert.deepEqual(titles(), ['First', 'Renamed']);
  const checkbox = rows()[0].children[1];
  checkbox.checked = true;
  await checkbox.fire('change');
  assert.deepEqual(titles(), ['Renamed']);
  assert.equal(completion.value, 'Open');
  assert.equal(priority.value, 'Low');
  assert.equal(tasks[0].completed, true);
  assert.equal(tasks[2].priority, 'Low');
  assert.ok(descendants(app).every(node => node.attributes.role !== 'alert' || node.hidden));
});

test('project default changes preserve filters and existing tasks; creation inherits the default', async () => {
  const { app, tasks, project, byId, titles } = await page();
  const defaults = byId('default-task-priority');
  assert.equal(defaults.value, 'Normal');
  assert.deepEqual(defaults.children.map(option => option.textContent), ['Low', 'Normal', 'High']);
  assert.ok(!defaults.disabled);
  const completion = byId('task-filter');
  const priority = byId('priority-filter');
  completion.value = 'Open';
  await completion.fire('change');
  priority.value = 'High';
  await priority.fire('change');
  const originalTasks = structuredClone(tasks);
  defaults.value = 'High';
  await defaults.fire('change');
  assert.equal(project.default_priority, 'High');
  assert.deepEqual(tasks, originalTasks);
  assert.deepEqual(titles(), ['Third']);
  assert.equal(completion.value, 'Open');
  assert.equal(priority.value, 'High');
  const input = byId('task-title');
  input.value = 'Inherited';
  const form = descendants(app).find(node => node.tag === 'form' && node.children.includes(input));
  await form.fire('submit');
  assert.deepEqual(titles(), ['Third', 'Inherited']);
  assert.equal(tasks.at(-1).priority, 'High');
  defaults.value = 'Low';
  await defaults.fire('change');
  assert.equal(tasks.at(-1).priority, 'High');
  assert.deepEqual(titles(), ['Third', 'Inherited']);
  assert.equal(completion.value, 'Open');
  assert.equal(priority.value, 'High');
});

test('due date saves and clears preserve both filters and other task data', async () => {
  const { tasks, byId, rows, titles } = await page();
  const completion = byId('task-filter');
  const priority = byId('priority-filter');
  completion.value = 'Open';
  await completion.fire('change');
  priority.value = 'High';
  await priority.fire('change');
  const before = structuredClone(tasks);
  const input = byId('task-due-date-3');
  assert.equal(input.type, 'text');
  assert.equal(input.value, '');
  const form = rows()[0].children.find(node => node.tag === 'form' && node.children.includes(input));
  assert.equal(form.children[0].textContent, 'Task due date');
  assert.equal(form.children[2].textContent, 'Save due date');
  input.value = '2024-02-29';
  await form.fire('submit');
  assert.deepEqual(tasks, before.map(task => task.id === 3 ? { ...task, due_date: '2024-02-29' } : task));
  assert.deepEqual(titles(), ['Third']);
  assert.equal(completion.value, 'Open');
  assert.equal(priority.value, 'High');
